using Mcacc.Core.Processes;
using Mcacc.Core.Quoting;

namespace Mcacc.Core.Terminal;

public static class PosixCommandFileBuilder
{
    private const string ConfigDir = EnvironmentScrub.ClaudeConfigDirVariable;

    public static string Build(ClaudeCodeLaunchRequest req)
    {
        string[] lines =
        [
            "#!/bin/zsh",
            "# Generated by MCACC - overwritten on every launch.",
            req.ClaudeConfigDir is null
                ? $"unset {ConfigDir}"
                : $"export {ConfigDir}={PosixQuoting.SingleQuote(req.ClaudeConfigDir)}",
            $"unset {string.Join(' ', EnvironmentScrub.Always)}",
            @"cd ""$HOME"" || exit 1",
            @"printf '\033]0;%s\007' " + PosixQuoting.SingleQuote(req.Title),
            // A login shell, so claude is found on the PATH the user's profile sets up.
            @"""${SHELL:-/bin/zsh}"" -l -i -c 'claude'",
            @"exec ""${SHELL:-/bin/zsh}"" -l -i",
        ];
        return string.Concat(lines.Select(line => line + "\n"));
    }
}
